/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  phases([[0,14],[14,40],[40,62],[62,80]]);
  v.sp = lin([[2,0],[8,1],[40,1],[46,0]]) * out;
  for (var i = 0; i < 5; i++) { var f = lin([[15 + i * 4, 0],[18 + i * 4, 1]]); var dx = (i == 2) ? 8 * lin([[62,0],[66,1]]) : 0; v['e'+i] = 'opacity: ' + (f * out).toFixed(3) + '; transform: translate(' + (-dx).toFixed(1) + 'px,' + (-10 * (1 - f)).toFixed(1) + 'px);'; }
  v.cl = lin([[42,0],[48,1]]) * out;
  var bad = (p >= 48 && p < 64);
  for (var i = 0; i < 5; i++) { var red = bad && (i == 1 || i == 2); v['cf'+i] = red ? 'rgba(192,57,43,0.12)' : 'rgba(30,127,79,0.08)'; v['cs'+i] = red ? '#C0392B' : '#1E7F4F'; }
  v.cc = bad ? 'CHP-1/2 overlap' : (p >= 64 ? 'all met' : '—');
  v.k0 = p >= 36 ? out : 0.25 * out; v.k1 = p >= 48 ? out : 0.25 * out; v.k2 = p >= 56 ? out : 0.25 * out; v.k3 = p >= 68 ? out : 0.25 * out;
  v.fin = (p >= 72 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
